package com.example.uniroom;
import android.os.*;import android.content.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.uniroom.model.Models.*;import com.example.uniroom.network.*;import retrofit2.*;
public class ProfileActivity extends AppCompatActivity{Session s;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_profile);s=new Session(this);findViewById(R.id.logout).setOnClickListener(v->{s.clear();startActivity(new Intent(this,LoginActivity.class));finishAffinity();});Client.api().profile(s.id()).enqueue(new Callback<ApiResponse>(){public void onResponse(Call<ApiResponse> c,Response<ApiResponse> r){if(r.body()!=null&&r.body().user!=null){User u=r.body().user;((TextView)findViewById(R.id.info)).setText("Name: "+u.first_name+" "+u.last_name+"\nStudent ID: "+u.student_id+"\nUsername: "+u.username+"\nEmail: "+u.email+"\nProgram: "+u.program+"\nSection: "+u.section_name);}}public void onFailure(Call<ApiResponse> c,Throwable t){}});}}
